import { useEffect, useState } from 'react';
import { Chart } from 'primereact/chart';
import { getMetrics } from '../services/api';

const metricLabels = {
  temperature: 'Температура (°C)',
  humidity: 'Вологість (%)',
  light: 'Освітлення (lx)',
  pressure: 'Тиск (гПа)',
  air_quality: 'Якість повітря (PM2.5, мкг/м³)',
  co2: 'CO₂ (ppm)',
  wind_speed: 'Швидкість вітру (м/с)',
  noise_level: 'Рівень шуму (дБ)',
  battery: 'Заряд батареї (%)'
};

export default function MetricsChart({ deviceId, dateRange, metricTypes }) {
  const [metricsByType, setMetricsByType] = useState({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!deviceId) return;

    setLoading(true);
    setError(null);

    const params = { deviceId };

    if (dateRange?.[0] && dateRange?.[1]) {
      params.start = dateRange[0].toISOString();
      params.end = dateRange[1].toISOString();
    }

    if (metricTypes?.length) {
      params.types = metricTypes;
    }

    getMetrics(params)
      .then((metrics) => {
        console.log('Отримані метрики:', metrics); // Логування для дебагу
        const grouped = {};
        for (const metric of metrics) {
          const { type, value, timestamp } = metric;
          if (!type || value == null || !timestamp) {
            console.warn('Пропущено некоректну метрику:', metric);
            continue;
          }
          if (!grouped[type]) {
            grouped[type] = { labels: [], data: [] };
          }
          grouped[type].labels.push(new Date(timestamp).toLocaleTimeString());
          grouped[type].data.push(value);
        }
        console.log('Згруповані метрики:', grouped); // Логування для дебагу
        setMetricsByType(grouped);
        setLoading(false);
      })
      .catch((err) => {
        console.error('Помилка отримання метрик:', err);
        setError('Не вдалося завантажити метрики');
        setLoading(false);
      });
  }, [deviceId, dateRange, metricTypes]);

  if (!deviceId) {
    return <div className="card">Виберіть пристрій для перегляду метрик</div>;
  }

  if (loading) {
    return <div className="card">Завантаження...</div>;
  }

  if (error) {
    return <div className="card">{error}</div>;
  }

  if (Object.keys(metricsByType).length === 0) {
    return <div className="card">Немає даних для відображення</div>;
  }

  return (
    <div className="grid">
      {Object.entries(metricsByType).map(([type, { labels, data }]) => (
        <div className="col-12 md:col-6" key={type}>
          <div className="card">
            <h4>{metricLabels[type] || type}</h4>
            <Chart
              type="line"
              data={{
                labels: labels || [],
                datasets: [{
                  label: metricLabels[type] || type,
                  data: data || [],
                  borderColor: '#42A5F5',
                  fill: false,
                }],
              }}
              options={{
                responsive: true,
                plugins: {
                  legend: { position: 'top' },
                },
              }}
            />
          </div>
        </div>
      ))}
    </div>
  );
}
